"""Staff booking/callback workspace, data protected by Bearer authentication."""
from fastapi import APIRouter
from fastapi.responses import HTMLResponse
router=APIRouter()
@router.get('/staff',response_class=HTMLResponse,include_in_schema=False)
def staff():
    return PAGE
PAGE = """<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Staff — Reception Studio</title><link rel="stylesheet" href="/static/style.css"></head><body><main class="wrap" style="padding-top:40px"><a href="/">← Reception Studio</a><h1 style="font-size:36px">Staff workspace</h1><p>Use the ADMIN_API_KEY from your private settings. The key stays in this tab’s memory.</p><form id="access" style="max-width:460px"><label for="key">Access key</label><input id="key" type="password" required autocomplete="off"><label for="business">Business</label><select id="business"><option value="hvac">ComfortWorks HVAC</option><option value="medical">CareCloud Medical</option></select><button class="button primary" style="margin-top:16px">Unlock &amp; refresh</button><button type="button" id="lock" class="button secondary">Lock</button></form><p id="status" role="status"></p><a href="/dashboard">Patient registration workspace ↗</a><h2>Appointments</h2><div id="bookings"></div><h2>Callback requests</h2><div id="inquiries"></div></main><script>
let key='';const el=id=>document.getElementById(id);async function request(url,options={}){const r=await fetch(url,{...options,headers:{Authorization:'Bearer '+key}});const j=await r.json();if(!r.ok)throw new Error(j.error?.message||'Request failed');return j.data;}
async function refresh(){try{const b=el('business').value;const [bookings,inquiries]=await Promise.all([request('/api/admin/'+b+'/bookings'),request('/api/admin/'+b+'/inquiries')]);el('bookings').replaceChildren();el('inquiries').replaceChildren();for(const row of bookings){const card=document.createElement('p');card.textContent=[row.customer_name,row.phone,row.service_id,row.starts_at,row.status,row.address].filter(Boolean).join(' · ');if(row.status==='confirmed'){const cancel=document.createElement('button');cancel.textContent='Cancel appointment';cancel.className='button secondary';cancel.onclick=async()=>{if(!confirm('Cancel this appointment?'))return;try{await request('/api/admin/'+b+'/bookings/'+row.id,{method:'DELETE'});await refresh();}catch(e){el('status').textContent=e.message;}};card.appendChild(cancel);}el('bookings').appendChild(card);}for(const row of inquiries){const card=document.createElement('p');card.textContent=[row.created_at,row.customer_name,row.phone,row.message,row.status].join(' · ');el('inquiries').appendChild(card);}el('status').textContent='Workspace unlocked. '+bookings.length+' appointments, '+inquiries.length+' callback requests.';}catch(e){el('status').textContent=e.message;el('bookings').replaceChildren();el('inquiries').replaceChildren();}}
el('access').onsubmit=e=>{e.preventDefault();if(el('key').value)key=el('key').value;el('key').value='';el('key').required=false;refresh();};el('lock').onclick=()=>{key='';el('bookings').replaceChildren();el('inquiries').replaceChildren();el('status').textContent='Locked';el('key').required=true;};el('business').onchange=()=>{el('bookings').replaceChildren();el('inquiries').replaceChildren();};
</script></body></html>"""
